sections.code:
const nombre = "Ana";
let edad = 25;
edad += 1;
console.log(`${nombre} tiene ${edad} años`);

let puntos = 10;
puntos += 5; // Actualiza el valor de la variable.
console.log(puntos); // 15

const usuario = { nombre: "Luna" };
// const impide reasignar la variable, no congelar el objeto.
usuario.nombre = "Sol";
console.log(usuario.nombre); // "Sol"

