const edad = 22;
// && exige que ambas condiciones sean verdaderas.
if (tieneCuenta && edad >= 18) {
  console.log("Acceso permitido");
}

const apodo = "";
// ?? solo usa el valor alternativo ante null o undefined.
const nombreVisible = apodo ?? "Invitado";
console.log(nombreVisible); // ""

