function calcularCompra(precio, cantidad, descuento) {
  if (precio < 0 || cantidad < 0 || descuento < 0) return null;
  const subtotal = precio * cantidad;
  const ahorro = subtotal * descuento / 100;
  return { subtotal, ahorro, total: subtotal - ahorro };
}
console.log(calcularCompra(100, 2, 10));
// { subtotal: 200, ahorro: 20, total: 180 }

