sections.code:
document.querySelector("#accion").addEventListener("click", () => {
  document.querySelector("#salida").textContent = "¡Hiciste clic!";
});

const boton = document.querySelector("#guardar");
if (boton) {
  boton.addEventListener("click", (evento) => {
    // currentTarget es el elemento que tiene el listener.
    evento.currentTarget.textContent = "Guardado";
  });
}

const formulario = document.querySelector("form");
formulario?.addEventListener("submit", (evento) => {
  evento.preventDefault(); // Evita el envío tradicional.
  console.log("Formulario listo para procesar");
});

