sections.code:
const esperar = ms => new Promise(resolve => setTimeout(resolve, ms));
async function iniciar() {
  console.log("Inicio");
  await esperar(500);
  console.log("Terminó la espera");
}
iniciar();

const tarea = new Promise((resolve, reject) => {
  const correcto = true;
  if (correcto) resolve("Operación terminada");
  else reject(new Error("La operación falló"));
});

tarea.then(console.log).catch(console.error);

async function cargarDato() {
  try {
    // await espera la resolución de la promesa dentro de esta función.
    const resultado = await Promise.resolve("Dato recibido");
    console.log(resultado);
  } catch (error) {
    console.error("No se pudo cargar:", error);
  }
}
cargarDato();

