const perfil = {nombre:"Ana", tema:"oscuro"};
localStorage.setItem("perfil", JSON.stringify(perfil));
const guardado = JSON.parse(localStorage.getItem("perfil"));
console.log(guardado.nombre);

localStorage.setItem("tema", "oscuro");
const tema = localStorage.getItem("tema");
console.log(tema); // "oscuro"

const preferencias = { fuente: 16, wrap: true };
// Web Storage guarda cadenas: serializamos el objeto.
localStorage.setItem("preferencias", JSON.stringify(preferencias));
const copia = JSON.parse(localStorage.getItem("preferencias"));
console.log(copia.fuente); // 16

