const ahora = new Date();
console.log(ahora.toLocaleDateString("es-AR"));
console.log("Ancho disponible:", window.innerWidth);

if ("geolocation" in navigator) {
  // La API existe; solicitar ubicación requiere permiso del usuario.
  console.log("Geolocalización disponible");
} else {
  console.log("Este entorno no ofrece geolocalización");
}

window.addEventListener("resize", () => {
  // innerWidth informa el ancho interior de la ventana.
  console.log("Ancho actual:", window.innerWidth);
});

